from pathlib import Path
import os,json,subprocess
roots=[('/root/iptvpn_bot','/root/project-secrets/iptvpn_bot'),('/opt/telegram-robot-leads','/root/project-secrets/telegram-robot-leads')]
for code,vault in roots:
 print('PROJECT',code)
 names=[]
 for p in Path(vault).rglob('*'):
  if p.is_file() and len(names)<35:
   names.append((p.relative_to(vault).suffix or '<no-extension>',p.stat().st_size))
 print('VAULT_COUNT',len(names),'EXT_AND_SIZE',names)
 print('CODE_VAULT_PATH_REFERENCE_COUNT',end=' ')
 count=0
 paths=[]
 for f in Path(code).rglob('*'):
  if not f.is_file() or f.is_symlink():continue
  if len(f.parts)-len(Path(code).parts)>4:continue
  try:
   st=f.stat()
   if st.st_size>800000 or st.st_size==0:continue
   s=f.read_text(errors='replace')
   if vault in s:
    count+=1
    if len(paths)<22:paths.append(str(f.relative_to(code)))
  except (OSError,ValueError):pass
 print(count,'FILES',paths)
print('PM2_REFERENCES_TO_VAULT')
r=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=25,env={**os.environ,'PM2_HOME':'/root/.pm2'})
if r.returncode==0:
 for app in json.loads(r.stdout):
  if app.get('name') not in ('iptvpn_bot','telegram-robot-leads'):continue
  env=app.get('pm2_env') or {}
  sensitive=[]
  for k,v in env.items():
   if isinstance(v,str):
    for t in ['/root/project-secrets/iptvpn_bot','/root/project-secrets/telegram-robot-leads','/home/ubuntu/telegram-leads-venv','/opt/telegram-leads-optin']:
     if t in v:sensitive.append(k)
  print('PM2',app.get('name'),'PATH_REF_FIELDS',sensitive)
else:print('PM2_ERROR_CODE',r.returncode)
print('SYSTEMD_REFERENCES_TO_VAULT')
for service in ['pm2-root','telegram-leads-activate-20261020']:
 p=Path('/etc/systemd/system')/(service+'.service')
 if p.is_file():
  t=p.read_text()
  print('SYSTEMD',service,[(q,q in t) for q in ['/root/project-secrets','/opt/telegram-leads-optin']])
print('VAULT_AUDIT_PASS')
